module activationFunction_tb ();

reg clk, reset, en;
reg [1023:0] input_fc;
wire [1023:0] output_fc;


localparam PERIOD = 100;

always
	#(PERIOD/2) clk = ~clk;

initial begin
	#0
	clk = 1'b0;
	reset = 1'b1;
	en = 0;
	input_fc = 1024';

	#PERIOD
	reset = 0;
	en = 1'b1;

	#PERIOD
	input_fc = 1024';

	#PERIOD
	$stop;
end

activationFunction UUT
(
	.clk(clk),
	.reset(reset),
	.en(en),
	.input_fc(input_fc),
	.output_fc(output_fc)
);

endmodule
